+void KeyboardBrightnessControl::onProfileUnload()
+{
+    m_isOffForIdle = false;
+    setLightSensorEnabled(false);
+    updateBacklight();
+}
+
+void KeyboardBrightnessControl::onIdleTimeout(std::chrono::milliseconds /*timeout*/)
+{
+    m_isOffForIdle = true;
+    updateBacklight();
+}
+
+void KeyboardBrightnessControl::onWakeupFromIdle()
+{
+    m_isOffForIdle = false;
+    updateBacklight();
+}
+
+void KeyboardBrightnessControl::updateBacklight()
+{
+    const bool turnOff = m_isOffForIdle || m_isOffForBrightLight;
+    if (turnOff == m_isTurnedOff) {
+        return;
+    }
+
+    if (turnOff) {
+        // Leave it alone if it's already off, e.g. because the display was dimmed or the user turned it off
+        const int brightness = keyboardBrightness();
+        if (brightness <= 0) {
+            return;
+        }
+        qCDebug(POWERDEVIL) << "KeyboardBrightnessControl: turning off keyboard backlight, idle:" << m_isOffForIdle << "bright light:" << m_isOffForBrightLight;
+        m_brightnessBeforeTurningOff = brightness;
+        m_isTurnedOff = true;
+        core()->keyboardBrightnessController()->setBrightness(0);
+    } else {
+        m_isTurnedOff = false;
+        // Don't override a brightness that was set in the meantime
+        if (keyboardBrightness() == 0) {
+            qCDebug(POWERDEVIL) << "KeyboardBrightnessControl: restoring keyboard backlight to" << m_brightnessBeforeTurningOff;
+            core()->keyboardBrightnessController()->setBrightness(m_brightnessBeforeTurningOff);
+        }
+    }
+}
+
+void KeyboardBrightnessControl::setLightSensorEnabled(bool enabled)
+{
+    if (m_turnOffInBrightLight == enabled) {
+        return;
     }
+    m_turnOffInBrightLight = enabled;
+
+    if (enabled) {
+        claimLightSensor();
+    } else {
+        releaseLightSensor();
+        m_isOffForBrightLight = false;
+        updateBacklight();
+    }
+}
+
+void KeyboardBrightnessControl::claimLightSensor()
+{
+    QDBusConnection bus = QDBusConnection::systemBus();
+    if (m_isLightSensorClaimed || !bus.interface()->isServiceRegistered(SENSOR_PROXY_SERVICE)) {
+        return;
+    }
+    m_isLightSensorClaimed = true;
+
+    bus.connect(SENSOR_PROXY_SERVICE,
+                SENSOR_PROXY_PATH,
+                DBUS_PROPERTIES_INTERFACE,
+                u"PropertiesChanged"_s,
+                this,
+                SLOT(onLightSensorPropertiesChanged(QString, QVariantMap, QStringList)));
+
+    QDBusMessage claim = QDBusMessage::createMethodCall(SENSOR_PROXY_SERVICE, SENSOR_PROXY_PATH, SENSOR_PROXY_INTERFACE, u"ClaimLight"_s);
+    bus.asyncCall(claim);
+
+    QDBusMessage getAll = QDBusMessage::createMethodCall(SENSOR_PROXY_SERVICE, SENSOR_PROXY_PATH, DBUS_PROPERTIES_INTERFACE, u"GetAll"_s);
+    getAll.setArguments({SENSOR_PROXY_INTERFACE});
+    auto watcher = new QDBusPendingCallWatcher(bus.asyncCall(getAll), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        const QDBusPendingReply<QVariantMap> reply = *watcher;
+        if (reply.isError()) {
+            qCWarning(POWERDEVIL) << "Failed to read the ambient light sensor:" << reply.error().message();
+            return;
+        }
+        if (m_isLightSensorClaimed) {
+            updateLightLevel(reply.value());
+        }
+    });
+}

-    m_defaultValue = profileSettings.keyboardBrightness();
-    return true;
+void KeyboardBrightnessControl::releaseLightSensor()
+{
+    if (!m_isLightSensorClaimed) {
+        return;
+    }
+    m_isLightSensorClaimed = false;
+
+    QDBusConnection bus = QDBusConnection::systemBus();
+    bus.disconnect(SENSOR_PROXY_SERVICE,
+                   SENSOR_PROXY_PATH,
+                   DBUS_PROPERTIES_INTERFACE,
+                   u"PropertiesChanged"_s,
+                   this,
+                   SLOT(onLightSensorPropertiesChanged(QString, QVariantMap, QStringList)));
+    bus.asyncCall(QDBusMessage::createMethodCall(SENSOR_PROXY_SERVICE, SENSOR_PROXY_PATH, SENSOR_PROXY_INTERFACE, u"ReleaseLight"_s));
+}
+
+void KeyboardBrightnessControl::onLightSensorPropertiesChanged(const QString &interfaceName,
+                                                               const QVariantMap &changedProperties,
+                                                               const QStringList & /*invalidatedProperties*/)
+{
+    if (interfaceName == SENSOR_PROXY_INTERFACE && m_isLightSensorClaimed) {
+        updateLightLevel(changedProperties);
+    }
+}
+
+void KeyboardBrightnessControl::updateLightLevel(const QVariantMap &properties)
+{
+    if (auto it = properties.constFind(u"HasAmbientLight"_s); it != properties.constEnd() && !it->toBool()) {
+        m_isLightLevelInLux = false;
+    }
+    if (auto it = properties.constFind(u"LightLevelUnit"_s); it != properties.constEnd()) {
+        m_isLightLevelInLux = it->toString() == u"lux"_s;
+    }
+
+    if (!m_isLightLevelInLux) {
+        m_isOffForBrightLight = false;
+    } else if (auto it = properties.constFind(u"LightLevel"_s); it != properties.constEnd()) {
+        const double lux = it->toDouble();
+        if (lux >= BRIGHT_LIGHT_LUX) {
+            m_isOffForBrightLight = true;
+        } else if (lux <= DIM_LIGHT_LUX) {
+            m_isOffForBrightLight = false;
+        }
+    }
+    updateBacklight();
 }

 void KeyboardBrightnessControl::onBrightnessChangedFromController(const KeyboardBrightnessLogic::BrightnessInfo &info)
